/*!40000 ALTER TABLE `resenia` DISABLE KEYS */;
INSERT INTO `resenia` VALUES (28,'2025-08-15','20:12:33','Cine total pero que manera de sufrir','Casi rompo el teclado de la bronca en una parte complicadisima, pero cuando lo pase salte de la silla festejando. Que pedazo de juegazo por dios, vale cada centavo.','4.5','dada@caca.com'),(28,'2025-11-05','23:15:00','Una experiencia inmersiva y memorable','Desde los primeros compases Red Dead Redemption 2 demuestra una ambicion artistica y de diseño sobresaliente. El mundo esta construido con un nivel de detalle que premia la curiosidad constante del jugador, mientras que la banda sonora y los efectos de sonido envuelven cada escena dandole una identidad propia. A nivel jugable, las mecanicas responden con precision y ofrecen suficiente variedad tactica para mantener el interes durante decenas de horas. Si bien en ciertos momentos el ritmo decae levemente por misiones secundarias algo reiterativas, el balance general es extraordinario. Una obra imprescindible para cualquier amante de los buenos videojuegos.','4.5','dada@gmail.com'),(28,'2025-12-19','01:40:22','Buen juego aunque le falto pulido en detalles','Red Dead Redemption 2 tiene ideas fantasticas y momentos memorables, aunque algunos bugs menores y decisiones de interfaz empañan un poco la experiencia. Con un par de actualizaciones de balance se convertira en un clasico indiscutible.','3.0','juan@gmail.coim'),(28,'2025-06-22','18:45:10','Una autentica joya','Impecable de principio a fin. Jugabilidad pulida, arte magnifico y una banda sonora que emociona. Imprescindible.','5.0','juan@gmail.com'),(28,'2025-02-14','11:24:15','Solido y entretenido, con altibajos menores','Red Dead Redemption 2 entrega una propuesta muy solida en lo que a su loop principal de juego respecta. El combate y el movimiento son agiles, los controles se sienten naturales y la curva de dificultad esta bien planteada. Sin embargo, hacia el tramo medio se percibe cierta repeticion en las estructuras de los objetivos y la inteligencia artificial puede tener deslices ocasionales. A pesar de estos puntos mejorables, la diversion que ofrece compensa con creces sus defectos y asegura una gran cantidad de horas de entretenimiento de calidad.','3.5','manaaddict@gmail.com'),(28,'2026-10-06','10:56:03.205326700','fghjjkfhg','íja','2.0','perez@gay'),(28,'2026-06-15','14:30:00','Una obra maestra absoluta','La historia de Arthur Morgan te llega al corazon. El mejor mundo abierto y narrativo que probe en mi vida.','5.0','pixelninja@gmail.com'),(28,'2025-05-10','16:30:00','Una evolucion que cumple con creces','Toma las bases de su formula y las refina en practicamente todos los aspectos. Mayor variedad de opciones, escenarios mas detallados y un ritmo que rara vez afloja. Un trabajo muy respetuoso con las expectativas de la comunidad.','4.0','questgiver@gmail.com'),(28,'2025-03-28','14:05:42','Divertidisimo para desconectar','Llegar cansado de la facultad o del laburo, prender la compu y mandarle mecha a Red Dead Redemption 2 es la mejor terapia. Cero vueltas, diversion pura y dura.','4.0','shadowrogue@gmail.com'),(28,'2025-09-30','21:50:18','No esperaba nada y me encontre oro puro','Lo compre sin mucha fe para pasar el rato un fin de semana y me volo la cabeza por completo. Los graficos son hermosos, la musica te pone la piel de gallina y el vicio es total.','5.0','stealthfox@gmail.com'),(32,'2025-09-30','01:40:22','Solido y entretenido, con altibajos menores','Destiny 2 entrega una propuesta muy solida en lo que a su loop principal de juego respecta. El combate y el movimiento son agiles, los controles se sienten naturales y la curva de dificultad esta bien planteada. Sin embargo, hacia el tramo medio se percibe cierta repeticion en las estructuras de los objetivos y la inteligencia artificial puede tener deslices ocasionales. A pesar de estos puntos mejorables, la diversion que ofrece compensa con creces sus defectos y asegura una gran cantidad de horas de entretenimiento de calidad.','3.5','admin@gmail.com'),(32,'2025-05-10','20:12:33','Juegazo absoluto, adios vida social','Dije \'juego una partidita de 20 minutos antes de dormir\' y de repente eran las 5 de la mañana y estaba viendo el amanecer. Hacia años que un juego no me enviciaba de esta manera. 10/10 totalmente destructivo para mi productividad.','5.0','dada@da'),(32,'2026-09-27','19:34:03.012030300','87ty','dsxfdsf','2.0','juan@gmail.coim'),(32,'2026-10-23','09:58:16.468145200','asd','dasdsa','2.0','juan@gmail.com'),(32,'2025-06-22','21:50:18','Gran narrativa con peso emocional y madurez','Lo que verdaderamente eleva a Destiny 2 por encima de la media es la madurez con la que aborda su historia. Los personajes estan solidamente construidos, con dilemas creibles y arcos de desarrollo que se van cocinando a fuego lento. No teme tomarse pausas contemplativas entre los momentos de mayor tension, lo que refuerza el impacto de sus climax narrativos. Acompañado de una direccion artistica impecable y actuaciones de voz de altisimo calibre, deja una huella emocional que perdura mucho despues de terminarlo.','4.5','mysticmage@gmail.com'),(32,'2025-03-28','18:45:10','Muy recomendable','Divertido, directo y con mecanicas muy bien calibradas. Cumple sobradamente lo que promete.','4.0','perez@gay'),(32,'2025-12-19','13:20:11','No esperaba nada y me encontre oro puro','Lo compre sin mucha fe para pasar el rato un fin de semana y me volo la cabeza por completo. Los graficos son hermosos, la musica te pone la piel de gallina y el vicio es total.','5.0','probandoooooooo@gmail.com'),(32,'2026-06-28','23:05:00','Tenés que hipotecar la casa','El gunplay es el mejor del mercado, pero te cobran hasta por respirar con los DLCs.','3','raidboss@yahoo.com'),(32,'2025-08-15','23:15:00','Cine total pero que manera de sufrir','Casi rompo el teclado de la bronca en una parte complicadisima, pero cuando lo pase salte de la silla festejando. Que pedazo de juegazo por dios, vale cada centavo.','4.5','santiagomalet229@gmail.com'),(32,'2026-01-24','15:55:04','Desafiante, justo y muy gratificante','Exige concentracion y paciencia para dominar sus sistemas, pero cada victoria en Destiny 2 se siente completamente ganada. El diseño de los encuentros mas complejos es brillante y te empuja a explotar al maximo todas las herramientas a tu disposicion.','4.5','shadowrogue@gmail.com'),(32,'2025-11-05','03:10:55','Una evolucion que cumple con creces','Toma las bases de su formula y las refina en practicamente todos los aspectos. Mayor variedad de opciones, escenarios mas detallados y un ritmo que rara vez afloja. Un trabajo muy respetuoso con las expectativas de la comunidad.','4.0','usuariosingrupo@gmail.com'),(41,'2025-06-22','01:40:22','Divertidisimo para desconectar','Llegar cansado de la facultad o del laburo, prender la compu y mandarle mecha a Little Nightmares es la mejor terapia. Cero vueltas, diversion pura y dura.','4.0','admin@gmail.com'),(41,'2025-09-30','13:20:11','Una autentica joya','Impecable de principio a fin. Jugabilidad pulida, arte magnifico y una banda sonora que emociona. Imprescindible.','5.0','cyberknight@yahoo.com'),(41,'2025-05-10','23:15:00','Un punto de inflexion para el genero','Es imposible evaluar Little Nightmares sin reconocer el impacto que genera en su genero. La fluidez de sus mecanicas, la inteligencia del diseño de escenarios y la riqueza de su universo establecen un nuevo estandar. El ritmo esta calibrado con precision, dosificando nuevas mecanicas y desafios a medida que avanzamos. Pequeños detalles visuales y una banda sonora emotiva terminan de redondear una experiencia practicamente redonda.','5.0','dada@caca.com'),(41,'2026-06-02','11:24:15','Gran narrativa con peso emocional y madurez','Lo que verdaderamente eleva a Little Nightmares por encima de la media es la madurez con la que aborda su historia. Los personajes estan solidamente construidos, con dilemas creibles y arcos de desarrollo que se van cocinando a fuego lento. No teme tomarse pausas contemplativas entre los momentos de mayor tension, lo que refuerza el impacto de sus climax narrativos. Acompañado de una direccion artistica impecable y actuaciones de voz de altisimo calibre, deja una huella emocional que perdura mucho despues de terminarlo.','4.5','perez@gay'),(41,'2025-08-15','03:10:55','Solido y entretenido, con altibajos menores','Little Nightmares entrega una propuesta muy solida en lo que a su loop principal de juego respecta. El combate y el movimiento son agiles, los controles se sienten naturales y la curva de dificultad esta bien planteada. Sin embargo, hacia el tramo medio se percibe cierta repeticion en las estructuras de los objetivos y la inteligencia artificial puede tener deslices ocasionales. A pesar de estos puntos mejorables, la diversion que ofrece compensa con creces sus defectos y asegura una gran cantidad de horas de entretenimiento de calidad.','3.5','santiago.malet.12@gmail.com'),(41,'2025-12-19','19:08:29','Desafiante, justo y muy gratificante','Exige concentracion y paciencia para dominar sus sistemas, pero cada victoria en Little Nightmares se siente completamente ganada. El diseño de los encuentros mas complejos es brillante y te empuja a explotar al maximo todas las herramientas a tu disposicion.','4.5','santiagomalet229@gmail.com'),(41,'2026-04-17','17:42:50','Un viaje de ida','Al principio me costo agarrarle la mano a los controles, pero una vez que te hace el click en la cabeza no podes parar. Totalmente recomendado para jugarlo con auriculares a todo volumen.','4.5','shadowrogue@gmail.com'),(41,'2026-01-24','22:33:14','Atmosfera envolvente y excelente direccion','La atmosfera que logra construir Little Nightmares es digna de elogio. La combinacion de iluminacion, direccion de arte y diseño sonoro genera una inmersion inmediata. Las mecanicas principales son intuitivas y el rendimiento tecnico responde muy bien.','4.0','sniperwolf@hotmail.com'),(41,'2026-03-08','00:05:40','Una experiencia inmersiva y memorable','Desde los primeros compases Little Nightmares demuestra una ambicion artistica y de diseño sobresaliente. El mundo esta construido con un nivel de detalle que premia la curiosidad constante del jugador, mientras que la banda sonora y los efectos de sonido envuelven cada escena dandole una identidad propia. A nivel jugable, las mecanicas responden con precision y ofrecen suficiente variedad tactica para mantener el interes durante decenas de horas. Si bien en ciertos momentos el ritmo decae levemente por misiones secundarias algo reiterativas, el balance general es extraordinario. Una obra imprescindible para cualquier amante de los buenos videojuegos.','4.5','stealthfox@gmail.com'),(41,'2025-11-05','15:55:04','Diseño de niveles y mecanicas de primer nivel','Hacia tiempo que no disfrutaba de una propuesta tan bien articulada como la de Little Nightmares. El diseño de niveles logra el equilibrio perfecto entre libertad de accion y orientacion sutil, evitando frustrar al jugador pero exigiendo atencion a los detalles del entorno. El sistema de progresion se siente organico y gratificante: cada nueva habilidad o mejora desbloqueada abre posibilidades reales de afrontar los desafios. Visualmente tiene momentos espectaculares y la optimizacion en general es muy solida. Recomendado sin lugar a dudas tanto para veteranos del genero como para recien llegados.','5.0','trophyhunter@yahoo.com'),(278,'2025-08-15','15:55:04','Juegazo absoluto, adios vida social','Dije \'juego una partidita de 20 minutos antes de dormir\' y de repente eran las 5 de la mañana y estaba viendo el amanecer. Hacia años que un juego no me enviciaba de esta manera. 10/10 totalmente destructivo para mi productividad.','5.0','cyberknight@yahoo.com'),(278,'2026-03-08','11:24:15','Diseño de niveles y mecanicas de primer nivel','Hacia tiempo que no disfrutaba de una propuesta tan bien articulada como la de Horizon Zero Dawn. El diseño de niveles logra el equilibrio perfecto entre libertad de accion y orientacion sutil, evitando frustrar al jugador pero exigiendo atencion a los detalles del entorno. El sistema de progresion se siente organico y gratificante: cada nueva habilidad o mejora desbloqueada abre posibilidades reales de afrontar los desafios. Visualmente tiene momentos espectaculares y la optimizacion en general es muy solida. Recomendado sin lugar a dudas tanto para veteranos del genero como para recien llegados.','5.0','glitchmaster@gmail.com'),(278,'2026-07-02','10:25:00','Cazar dinosaurios robot','El concepto es rarísimo pero funciona de diez. Aloy es tremenda protagonista.','4','ironblacksmith@outlook.com'),(278,'2026-09-08','16:28:30.976684100','dada','da','2.0','juan@gmail.coim'),(278,'2026-10-17','16:43:22.398800900','dada','asd','2.0','juan@gmail.com'),(278,'2025-06-22','13:20:11','Una autentica joya','Impecable de principio a fin. Jugabilidad pulida, arte magnifico y una banda sonora que emociona. Imprescindible.','5.0','perez@gay'),(278,'2025-09-30','19:08:29','Divertidisimo para desconectar','Llegar cansado de la facultad o del laburo, prender la compu y mandarle mecha a Horizon Zero Dawn es la mejor terapia. Cero vueltas, diversion pura y dura.','4.0','sniperwolf@hotmail.com'),(278,'2025-12-19','00:05:40','Desafiante, justo y muy gratificante','Exige concentracion y paciencia para dominar sus sistemas, pero cada victoria en Horizon Zero Dawn se siente completamente ganada. El diseño de los encuentros mas complejos es brillante y te empuja a explotar al maximo todas las herramientas a tu disposicion.','4.5','usuario@gmail.com'),(278,'2025-11-05','22:33:14','Muy recomendable','Divertido, directo y con mecanicas muy bien calibradas. Cumple sobradamente lo que promete.','4.0','usuariosingrupo@gmail.com'),(278,'2026-01-24','17:42:50','Una experiencia inmersiva y memorable','Desde los primeros compases Horizon Zero Dawn demuestra una ambicion artistica y de diseño sobresaliente. El mundo esta construido con un nivel de detalle que premia la curiosidad constante del jugador, mientras que l